package com.shopsphere;import static org.assertj.core.api.Assertions.assertThat;import java.time.Duration;import org.junit.jupiter.api.Test;import org.testcontainers.containers.GenericContainer;import org.testcontainers.junit.jupiter.*;import io.lettuce.core.RedisClient;
@Testcontainers(disabledWithoutDocker=true)class CartPersistenceContainerTest{@Container static GenericContainer<?>redis=new GenericContainer<>("redis:7.4-alpine").withExposedPorts(6379);@Test void valueAndTtlRoundTrip(){var client=RedisClient.create("redis://"+redis.getHost()+":"+redis.getMappedPort(6379));try(var connection=client.connect()){connection.sync().setex("shopsphere:cart:test",60,"{}");assertThat(connection.sync().get("shopsphere:cart:test")).isEqualTo("{}");assertThat(connection.sync().ttl("shopsphere:cart:test")).isPositive();}finally{client.shutdown(Duration.ZERO,Duration.ZERO);}}}
